## Export the store

```ts
// store.ts
import { configureStore } from '@reduxjs/toolkit';
import rootReducer from './rootReducer';

export const store = configureStore({ reducer: rootReducer });
export type RootState  = ReturnType<typeof store.getState>;
export type AppDispatch = typeof store.dispatch;
```

## Use it outside React

```ts
// apiClient.ts
import axios from 'axios';
import { store } from './store';

axios.interceptors.request.use((config) => {
  const token = store.getState().auth.token;
  if (token) config.headers.Authorization = `Bearer ${token}`;
  return config;
});

axios.interceptors.response.use(
  (res) => res,
  (err) => {
    if (err.response?.status === 401) {
      store.dispatch({ type: 'auth/logout' });
    }
    return Promise.reject(err);
  },
);
```

## WebSocket example

```ts
// websocket.ts
import { store } from './store';
import { messageReceived } from './features/chat/chatSlice';

const ws = new WebSocket('wss://api.example.com/ws');

ws.onmessage = (event) => {
  const message = JSON.parse(event.data);
  store.dispatch(messageReceived(message)); // write to Redux from outside React
};
```

## Caveats

- **Circular imports** — store.ts imports reducers; reducers should not import store.ts. Keep the dependency direction one-way.
- **Testing** — code that imports the real store is harder to unit-test. Prefer passing dispatch/getState explicitly when possible.
- **Server-side rendering** — on the server there is a new store per request; importing a singleton store breaks SSR. Scope direct store access to client-only code.

