## Pattern 1 — per-slice reset action

```ts
const cartSlice = createSlice({
  name: 'cart',
  initialState,
  reducers: {
    reset: () => initialState, // returns the default state
    addItem: (state, action: PayloadAction<CartItem>) => {
      state.items.push(action.payload);
    },
  },
});

// Dispatch on logout:
dispatch(cartSlice.actions.reset());
dispatch(userSlice.actions.reset());
// ... repeat for every slice
```

Simple but requires dispatching multiple actions.

## Pattern 2 — root reducer wrapper (recommended for full reset)

```ts
// store.ts
import { combineReducers } from '@reduxjs/toolkit';

const appReducer = combineReducers({
  cart:    cartReducer,
  user:    userReducer,
  session: sessionReducer,
});

const rootReducer: typeof appReducer = (state, action) => {
  if (action.type === 'app/reset') {
    // passing undefined makes every slice use its default parameter
    return appReducer(undefined, action);
  }
  return appReducer(state, action);
};

export const store = configureStore({ reducer: rootReducer });
```

```ts
// On logout:
dispatch({ type: 'app/reset' });
```

One action resets everything — clean for a logout flow.

## Pattern 3 — redux-persist

```ts
import { persistor } from './store';

async function logout() {
  dispatch({ type: 'app/reset' });  // clear in-memory state
  await persistor.purge();          // clear persisted storage
}
```

