## Step 1 — typed hooks in hooks.ts

```ts
import { useDispatch, useSelector } from 'react-redux';
import type { RootState, AppDispatch } from './store';

export const useAppDispatch = () => useDispatch<AppDispatch>();
export const useAppSelector = useSelector.withTypes<RootState>();
// Or:
// export const useAppSelector: TypedUseSelectorHook<RootState> = useSelector;
```

## Step 2 — use in components

```tsx
import { useAppSelector, useAppDispatch } from '@/app/hooks';
import { increment } from '@/features/counter/counterSlice';

function Counter() {
  const count    = useAppSelector((state) => state.counter.value);
  const dispatch = useAppDispatch();

  return <button onClick={() => dispatch(increment())}>{count}</button>;
}
```

## Step 3 — Provider at the root

```tsx
// app/layout.tsx (Next.js App Router with a client wrapper)
'use client';
import { Provider } from 'react-redux';
import { store } from '@/app/store';

export function Providers({ children }: { children: React.ReactNode }) {
  return <Provider store={store}>{children}</Provider>;
}
```

## Outside React

```ts
import { store } from '@/app/store';

export function getAuthToken(): string | null {
  return store.getState().auth.token;
}
```

## Anti-patterns to avoid

- `import { store } from './store'` inside a React component — bypasses react-redux's subscription system, so the component won't re-render on state changes.
- Passing `store` as a prop — that breaks component reusability.
- Accessing state in a render without `useSelector` — the component won't react to changes.

