```ts
import { useDispatch, useSelector } from 'react-redux';
import type { RootState, AppDispatch } from './store';

export const useAppDispatch = () => useDispatch<AppDispatch>();
export const useAppSelector = useSelector.withTypes<RootState>();
```

## Adım 2 — Bileşenlerde Kullan

```tsx
import { useAppSelector, useAppDispatch } from '@/app/hooks';
import { increment } from '@/features/counter/counterSlice';

function Counter() {
  const count    = useAppSelector((state) => state.counter.value);
  const dispatch = useAppDispatch();

  return <button onClick={() => dispatch(increment())}>{count}</button>;
}
```

## Adım 3 — Kökte Provider

```tsx
// app/layout.tsx (Next.js App Router)
'use client';
import { Provider } from 'react-redux';
import { store } from '@/app/store';

export function Providers({ children }: { children: React.ReactNode }) {
  return <Provider store={store}>{children}</Provider>;
}
```

## Kaçınılması Gereken Anti-Pattern'lar

- React bileşeninde `import { store } from './store'` — react-redux'un abonelik sistemini atlar, bileşen durum değişikliklerinde yeniden render edilmez.
- `useSelector` olmadan render'da duruma erişmek — bileşen değişikliklere tepki vermez.

